<?php authorizeAdmin($u); $editing=!empty($_GET['id'])?row('SELECT * FROM users WHERE id=?',[(int)$_GET['id']]):null; $data=$_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='user'?$_POST:($editing??[]); $dataRoles=is_array($data['roles']??null)?$data['roles']:json_decode($data['roles']??'[]',true); $people=rows('SELECT u.*,d.name department FROM users u JOIN departments d ON d.id=u.department_id ORDER BY name'); ?>
<p class="page-intro">Mantén los datos personales, la fecha de nacimiento y los roles. Asigna los responsables de las dependencias desde Designaciones; cada trámite conserva a sus aprobadores originales.</p><section class="panel"><div class="panel-header"><h2>Directorio de funcionarios</h2><a class="text-link" href="/?page=import">Importar desde Excel →</a></div><div class="table-wrap"><table><thead><tr><th>Funcionario</th><th>Cargo / dependencia</th><th>Roles</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($people as $p): ?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['identification'].' · '.$p['username'])?></small></td><td><?=e($p['job_title'])?><small><?=e($p['department'])?></small></td><td><?=e(implode(', ',array_map('roleLabel',roles($p)))?:'Solicitante')?></td><td><?=(int)$p['active']?'Activo':'Inactivo'?></td><td><a class="text-link" href="/?page=users&id=<?=(int)$p['id']?>#user-form">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="detail-columns"><section class="panel form-panel" id="user-form"><h2><?=$editing?'Editar funcionario':'Nuevo funcionario'?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="user"><input type="hidden" name="id" value="<?=e($editing['id']??'')?>"><div class="form-grid"><?php foreach(['name'=>'Nombre completo','identification'=>'Cédula','username'=>'Usuario','email'=>'Correo electrónico'] as $key=>$label): ?><label><?=e($label)?><input name="<?=$key?>" value="<?=e($data[$key]??'')?>" <?=in_array($key,['code','grade'])?'':'required'?> <?=$key==='email'?'type="email"':''?> maxlength="180"></label><?php endforeach; ?><?php $catalog=jobCatalog(); $selectedTitle=trim($data['job_title']??''); $selectedGrade=trim($data['grade']??''); $catalogJobs=[]; foreach($catalog as $entry)$catalogJobs[$entry['job_id']]=$entry; ?>
<label>Cargo<select name="job_title" id="user-job" required><option value="">Selecciona un cargo</option><?php foreach($catalogJobs as $entry): ?><option value="<?=e($entry['title'])?>" data-code="<?=e($entry['code'])?>" <?=$selectedTitle===$entry['title']?'selected':''?>><?=e($entry['title'])?></option><?php endforeach; ?></select><small><a href="/?page=jobs">Administrar cargos, códigos y grados</a></small></label>
<label>Código<input name="code" id="user-job-code" readonly value="<?=e($data['code']??'')?>"><small>Se carga automáticamente según el cargo.</small></label>
<label>Grado<select name="grade" id="user-job-grade" data-legacy-job="<?=e($editing['job_title']??'')?>" data-legacy-blank="<?=($editing && $editing['grade']==='')?'1':'0'?>" <?=($editing && $editing['grade']==='')?'':'required'?>><option value="">Selecciona un grado</option><?php foreach($catalog as $entry): ?><option value="<?=e($entry['grade'])?>" data-job="<?=e($entry['title'])?>" <?=($entry['title']===$selectedTitle && $entry['grade']===$selectedGrade)?'selected':''?>><?=e($entry['grade']===''?'Sin grado registrado':$entry['grade'])?></option><?php endforeach; ?></select></label>
<label>Vinculación<select name="appointment_type"><?php foreach(['Carrera administrativa','Libre nombramiento y remoción','Provisional','Trabajador oficial'] as $v): ?><option <?=($data['appointment_type']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach; ?></select></label><label>Dependencia<select name="department_id" required><?php foreach(rows('SELECT * FROM departments ORDER BY name') as $d): ?><option value="<?=$d['id']?>" <?=(int)($data['department_id']??0)===(int)$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach; ?></select></label><label>Fecha de nacimiento<input type="date" name="birth_date" max="<?=date('Y-m-d',strtotime('-1 day'))?>" value="<?=e($data['birth_date']??'')?>"><small>Requerida para validar el beneficio de Cumpleaños.</small></label><label>Clasificación de alto rango<select name="high_rank"><?php foreach([''=>'No aplica','Asesor de Despacho'=>'Asesor de Despacho','Secretario de Despacho'=>'Secretario de Despacho','Jefe de Oficina'=>'Jefe de Oficina'] as $v=>$l): ?><option value="<?=e($v)?>" <?=($data['high_rank']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach; ?></select></label><label>Estado<select name="active"><option value="1">Activo</option><option value="0" <?=(isset($data['active']) && !(int)$data['active'])?'selected':''?>>Inactivo</option></select></label><?php if(!$editing): ?><label>Contraseña inicial<input name="initial_password" type="password" required minlength="12" autocomplete="new-password"><small>El funcionario deberá cambiarla al ingresar.</small></label><?php endif; ?></div><fieldset><legend>Roles adicionales al de solicitante</legend><div class="checks"><?php foreach(['admin'=>'Administrador de Talento Humano','manager'=>'Jefe inmediato','subsecretary'=>'Subsecretario','mayor'=>'Alcalde','payroll'=>'Nómina'] as $v=>$l): ?><label><input type="checkbox" name="roles[]" value="<?=$v?>" <?=in_array($v,$dataRoles,true)?'checked':''?>> <?=e($l)?></label><?php endforeach; ?></div></fieldset><button class="button">Guardar funcionario</button></form></section>
<aside><section class="panel form-panel"><h2>Nueva dependencia</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="department"><label>Nombre<input name="name" required maxlength="180"></label><button class="button secondary">Crear dependencia</button></form></section><?php if($editing): ?><section class="panel form-panel"><h2>Restablecer acceso</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><label>Nueva contraseña temporal<input name="initial_password" type="password" required minlength="12" autocomplete="new-password"></label><button class="button secondary">Restablecer contraseña</button></form></section><?php endif; ?></aside></div>
